<template>
  <Teleport to="body"><Transition name="detail-drawer"><div class="detail-drawer" role="dialog" aria-modal="true">
    <button class="detail-backdrop" type="button" aria-label="Dismiss overlay" @click="emit('close')" />
    <section class="detail-panel">
      <header class="detail-header"><div><p>Task</p><h2>{{ details?.subject || "Task details" }}</h2><span>{{ details?.project_name || "Pomas" }}<template v-if="details"> · {{ details.name }}</template></span></div><button type="button" aria-label="Close" @click="emit('close')">×</button></header>
      <div v-if="loading" class="detail-state"><span class="spinner" /><p>Loading task…</p></div>
      <div v-else-if="error" class="detail-state"><strong>Could not load this task.</strong><p>{{ error }}</p><button class="detail-secondary" type="button" @click="loadTask">Try again</button></div>
      <template v-else-if="details">
        <div class="detail-title-row"><div class="title-flags"><span :class="['detail-priority', `priority-${details.priority.toLowerCase()}`]">{{ details.priority }}</span><span v-if="details.is_milestone" class="milestone">★ Milestone</span></div></div>
        <section class="detail-section detail-overview"><h3>Overview</h3><dl class="detail-grid"><div><dt>Status</dt><dd><span :class="['status-pill', `status-${details.status.toLowerCase().replaceAll(' ', '-')}`]">{{ details.status }}</span></dd></div><div><dt>Progress</dt><dd>{{ details.progress || 0 }}%</dd></div><div><dt>Start date</dt><dd>{{ formatDate(details.exp_start_date) }}</dd></div><div><dt>Due date</dt><dd>{{ formatDate(details.exp_end_date) }}</dd></div><div><dt>Estimated effort</dt><dd>{{ details.expected_time ? `${details.expected_time} hours` : 'Not set' }}</dd></div><div><dt>Assignment</dt><dd>{{ details.assignees.length ? `${details.assignees.length} member${details.assignees.length === 1 ? '' : 's'}` : 'Unassigned' }}</dd></div></dl></section>
        <section class="detail-section"><h3>Assigned to</h3><div v-if="details.assignees.length" class="detail-assignees"><span v-for="user in details.assignees" :key="user"><i>{{ initials(user) }}</i><b>{{ user }}</b></span></div><div v-else class="unassigned-state">No one has taken this task yet.</div></section>
        <section class="detail-section"><h3>Description</h3><div class="description">{{ details.description || 'No description was added.' }}</div></section>
        <section v-if="details.submissions.length" class="detail-section submitted-section"><h3>Submitted work</h3><article v-for="submission in details.submissions" :key="submission.name" class="submission-card"><header><span class="submission-avatar">{{ initials(submission.submitted_by) }}</span><div><strong>{{ submission.submitted_by }}</strong><small>{{ formatTimestamp(submission.submitted_on) }}</small></div></header><p v-if="submission.description">{{ submission.description }}</p><div v-if="submission.files.length" class="submission-files"><button v-for="file in submission.files" :key="file.name" class="submission-file" type="button" @click="openFile(file)"><span class="file-kind">{{ fileExtension(file.file_name) }}</span><span><b>{{ file.file_name }}</b><small>{{ file.repository_path || 'Attached file' }}</small></span><em>↗</em></button></div></article></section>
        <p v-if="actionMessage" :class="['viewport-notice', actionError ? 'is-error' : 'is-success']">{{ actionMessage }}</p>
        <footer class="detail-actions"><button class="detail-secondary" type="button" @click="emit('close')">Close</button><button v-if="details.can_edit" class="detail-secondary" type="button" @click="emit('edit', details)">Edit</button><button v-if="details.can_review" class="detail-secondary" type="button" :disabled="working" @click="reviewTask('reject')">Reject</button><button v-if="details.can_review" class="detail-primary" type="button" :disabled="working" @click="reviewTask('approve')">Complete</button><button v-if="details.can_submit" class="detail-primary desktop-submit" type="button" @click="emit('submit', details)">Submit</button><button v-if="details.can_take" class="detail-primary" type="button" :disabled="working" @click="takeTask">{{ working ? 'Taking…' : 'Take task' }}</button><button v-if="details.can_delete" class="detail-delete" type="button" @click="deleteOpen = true">Delete task</button></footer>
      </template>
    </section>
    <div v-if="previewFile" class="file-modal" role="dialog" aria-modal="true"><button class="detail-backdrop" type="button" aria-label="Dismiss overlay" @click="previewFile = null" /><section class="file-preview-panel"><header><div><p>File preview</p><strong>{{ previewFile.file_name }}</strong></div><button type="button" aria-label="Close" @click="previewFile = null">×</button></header><img :src="submissionFileUrl(previewFile.name)" :alt="previewFile.file_name" /><a :href="submissionFileUrl(previewFile.name)" target="_blank" rel="noopener">Open original</a></section></div>
    <div v-if="fileChoice" class="file-modal" role="dialog" aria-modal="true"><button class="detail-backdrop" type="button" aria-label="Dismiss overlay" @click="fileChoice = null" /><section class="file-choice-panel"><button type="button" aria-label="Close" @click="fileChoice = null">×</button><div class="file-choice-icon">{{ fileExtension(fileChoice.file_name) }}</div><h3>{{ fileChoice.file_name }}</h3><p>This type of file opens in the app chosen by your device.</p><a class="detail-primary" :href="submissionFileUrl(fileChoice.name)" target="_blank" rel="noopener">Open file</a><a class="detail-secondary" :href="submissionFileUrl(fileChoice.name)" download>Download</a></section></div>
    <div v-if="deleteOpen" class="delete-backdrop" role="dialog" aria-modal="true"><button class="detail-backdrop" type="button" aria-label="Dismiss overlay" @click="deleteOpen = false" /><section class="task-delete-modal"><div class="task-delete-icon">!</div><div><p>Delete task</p><h3>Are you sure?</h3></div><span>This permanently deletes <b>{{ details?.subject }}</b>.</span><footer><button class="detail-secondary" type="button" :disabled="deleting" @click="deleteOpen = false">Cancel</button><button class="detail-delete" type="button" :disabled="deleting" @click="deleteTask">{{ deleting ? 'Deleting…' : 'Delete' }}</button></footer></section></div>
  </div></Transition></Teleport>
</template>
<script setup lang="ts">
import { onBeforeUnmount, onMounted, ref } from 'vue'
import { callPms, type SubmittedWorkFile, type TaskDetails } from '../services/api'
const props = defineProps<{ task: string }>()
const emit = defineEmits<{ close: []; taken: [task: TaskDetails]; submit: [task: TaskDetails]; edit: [task: TaskDetails]; updated: [task: TaskDetails]; deleted: [task: string] }>()
const details = ref<TaskDetails | null>(null), loading = ref(true), working = ref(false), deleting = ref(false), deleteOpen = ref(false), error = ref(''), actionMessage = ref(''), actionError = ref(false), previewFile = ref<SubmittedWorkFile | null>(null), fileChoice = ref<SubmittedWorkFile | null>(null)
const previousOverflow = document.body.style.overflow
onMounted(() => { document.body.style.overflow = 'hidden'; document.addEventListener('keydown', onKey); loadTask() })
onBeforeUnmount(() => { document.body.style.overflow = previousOverflow; document.removeEventListener('keydown', onKey) })
function onKey(event: KeyboardEvent) { if (event.key === 'Escape') { if (deleteOpen.value) deleteOpen.value = false; else if (previewFile.value) previewFile.value = null; else if (fileChoice.value) fileChoice.value = null; else emit('close') } }
async function loadTask() { loading.value = true; error.value = ''; try { details.value = await callPms<TaskDetails>('pms.api.get_task_details', { task: props.task }) } catch (reason) { error.value = reason instanceof Error ? reason.message : 'Unable to load this task.' } finally { loading.value = false } }
async function takeTask() { working.value = true; try { const task = await callPms<TaskDetails>('pms.api.take_task', { task: props.task }); details.value = task; emit('taken', task) } finally { working.value = false } }
async function reviewTask(action: 'approve' | 'reject') { working.value = true; try { const task = await callPms<TaskDetails>('pms.api.review_task', { task: props.task, action }); details.value = task; emit('updated', task) } finally { working.value = false } }
async function deleteTask() { deleting.value = true; try { await callPms('pms.api.delete_task', { task: props.task }); emit('deleted', props.task); emit('close') } catch (reason) { deleteOpen.value = false; actionError.value = true; actionMessage.value = reason instanceof Error ? reason.message : 'Unable to delete this task.' } finally { deleting.value = false } }
function openFile(file: SubmittedWorkFile) { if (/\.(png|jpe?g|gif|webp|svg)$/i.test(file.file_name)) previewFile.value = file; else fileChoice.value = file }
function initials(value: string) { return value.split(/[@.\s]+/).filter(Boolean).slice(0, 2).map(part => part[0]?.toUpperCase()).join('') }
function formatDate(value?: string) { return value ? new Intl.DateTimeFormat(undefined, { month: 'short', day: 'numeric', year: 'numeric' }).format(new Date(`${value}T00:00:00`)) : 'Not set' }
function formatTimestamp(value?: string) { return value ? new Intl.DateTimeFormat(undefined, { month: 'short', day: 'numeric', year: 'numeric', hour: 'numeric', minute: '2-digit' }).format(new Date(value)) : 'Submitted' }
function fileExtension(value: string) { return (value.split('.').pop() || 'file').slice(0, 4).toUpperCase() }
function submissionFileUrl(file: string) { return '/api/method/pms.api.open_submission_file?task=' + encodeURIComponent(props.task) + '&file=' + encodeURIComponent(file) }
</script>
